use kni_core::reference_slice;
use kni_core::lever_api;
use kni_core::boundary_bias;
use reference_slice::{Point,ReferenceRing,Span};
fn main(){let a:Vec<String>=std::env::args().collect();let text=std::fs::read_to_string(&a[1]).unwrap();let mut lines=text.lines();let h:Vec<&str>=lines.next().unwrap().split_whitespace().collect();let scale:f64=h[1].parse().unwrap();let ox:f64=h[2].parse().unwrap();let oy:f64=h[3].parse().unwrap();let mut rings=vec![];let mut r:Option<ReferenceRing>=None;
 for l in lines{let v:Vec<&str>=l.split_whitespace().collect();if v.is_empty(){continue;}let f=|i:usize|v[i].parse::<f64>().unwrap();match v[0]{"R"=>{if let Some(r)=r.take(){rings.push(r);}r=Some(ReferenceRing{start:Point{x:f(1),y:f(2)},spans:vec![]});},"L"=>r.as_mut().unwrap().spans.push(Span::Line{end:Point{x:f(1),y:f(2)}}),"C"=>r.as_mut().unwrap().spans.push(Span::Cubic{control_one:Point{x:f(1),y:f(2)},control_two:Point{x:f(3),y:f(4)},end:Point{x:f(5),y:f(6)}}),_=>()}}
 if let Some(r)=r{rings.push(r);}let (w,hg,ink)=kni_core::capture::decode_png_gray(&std::fs::read(&a[2]).unwrap()).unwrap();let mask=lever_api::SourceMask{w,h:hg,ink,scale,origin:(-ox*scale,-oy*scale)};let before=lever_api::hash_rings(&rings);let rep=boundary_bias::measure(&rings,&mask).unwrap();assert_eq!(before,lever_api::hash_rings(&rings));println!("ring\tspan\tt\tx_px\ty_px\tsigned_offset_px");for s in &rep.samples{println!("{}\t{}\t{}\t{}\t{}\t{}",s.ring,s.span,s.t,s.x_px,s.y_px,s.signed_offset_px);}eprintln!("samples={} mean_px={} median_px={} min_px={} max_px={} source_segments={} hash_before_after={:x}",rep.samples.len(),rep.mean_px,rep.median_px,rep.min_px,rep.max_px,rep.source_segments,before);}
